215	/**
216	 * Rank a room's members for the final scoreboard: score DESC, then elapsed
217	 * time ASC (a null time counts as slowest). "tie" only when score AND time
218	 * both match (or both times are null); slower equal-scorers get "loss". Rows
219	 * carry elapsedMs so clients can show how a tie was broken. Shared by
220	 * settleMatch AND snapshotFor so live results and resumes can never disagree.
221	 */
222	function rankRoom(room) {
223	  const timeKey = (uid) => (room.times[uid] == null ? Infinity : room.times[uid]);
224	  const ranked = room.members
225	    .map((uid) => ({ uid, score: room.scores[uid] ?? 0, elapsedMs: room.times[uid] ?? null }))
226	    .sort((a, b) => b.score - a.score || timeKey(a.uid) - timeKey(b.uid));
227	  const best = ranked[0];
228	  const sameAsBest = (e) => e.score === best.score && timeKey(e.uid) === timeKey(best.uid);
229	  const winners = ranked.filter(sameAsBest);
230	  return ranked.map((e) => ({
231	    ...publicUser(players.get(e.uid)?.user),
232	    id: e.uid,
233	    score: e.score,
234	    elapsedMs: e.elapsedMs,
235	    outcome: !sameAsBest(e) ? "loss" : winners.length > 1 ? "tie" : "win",
